  "studio.voiceClone.script.normalDuration": "~60 seconds",
  "studio.voiceClone.script.professionalDuration": "~90 seconds",
  "studio.voiceClone.script.quickBody":
    "Hi! Are you ready for today?\nLet me count: 3, 7, and 12.\nIt's a quarter past three — perfect timing.\nI feel cheerful and calm at the same time.\nShort sentence. And now a longer sentence about a €4.50 recipe you can make in 20 minutes.",
  "studio.voiceClone.script.normalBody":
    "Good morning! Welcome to our kitchen.\nImagine: 5 people, 2 dishes, 1 big table.\nIt costs €12.80 and takes about 45 minutes.\nHow do you feel today — curious, excited, or calm?\nShort sentence. Now a longer sentence about fresh ingredients you can serve at 6:30 PM with a smile.",
  "studio.voiceClone.script.professionalBody":
    "Welcome. Today we take you behind the scenes.\nWe start at 9:00 AM, work in 3 phases, and wrap up around 5:45 PM.\nThe budget is €250 — including 15% for fresh produce.\nCan you feel the energy? And the calm between sentences?\nShort sentence.\nA longer sentence explains why community, flavor, and stories form one recognizable voice — exactly what you need for videos, tutorials, and brand hosts.",
